import xml.etree.ElementTree as ET
from attrs import define, field


def create_interoperability_probe_object(data):
    raw_data = data.replace("\n", "").replace("\t", "")
    iteroperability_probe_paramts = InteroperabilityProbe.from_string(raw_data)
    return iteroperability_probe_paramts


def check_groups(root, attributes):
    for child in root:
        if child.tag == "group":
            status = child.findtext("status")
            generated = child.findtext("generated")
            attributes.setdefault("groups", {}).update(
                {child.text.replace("\n", "").replace(" ", ""): {"status": status, "generated": generated}}
            )
        if child.tag == "result-groups":
            attributes.update({"result_groups": child.text})


def check_description_and_applied_params(root, attributes):
    for child in root.findall("summary/"):
        if child.tag != "verdicts":
            attributes.update({child.tag: child.text})


def check_verdicts_params(root, attributes):
    for child in root.findall("summary/verdicts/"):
        if child.tag == "no-interop":
            attributes.update({"no_interop": child.text})
        elif child.tag == "not-generated":
            attributes.update(({"not_generated": child.text}))
        else:
            attributes.update({child.tag: child.text})


@define
class InteroperabilityProbe:
    total = field(converter=int)
    interop = field(converter=int)
    no_interop = field(converter=int)
    unknown = field(converter=int)
    description = field()
    applied = field()
    groups = field()
    result_groups = field()

    @classmethod
    def from_string(cls, data):
        root = ET.fromstring(data)

        attributes = {"total": 0, "interop": 0, "no_interop": 0, "unknown": 0, "result_groups": ""}

        check_verdicts_params(root, attributes)
        check_groups(root, attributes)
        check_description_and_applied_params(root, attributes)

        return cls(**attributes)
